CREATE FUNCTION public.private_invitation_preparation_guard() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF (TG_OP='INSERT' AND NEW.recipient_workspace_id IS NULL) OR (TG_OP='UPDATE' AND NEW.generation IS DISTINCT FROM OLD.generation) THEN RAISE EXCEPTION 'Private invitation preparation requires approved durable destination rate limiting'; END IF; RETURN NEW; END $$;
COMMENT ON FUNCTION public.private_invitation_preparation_guard() IS 'Fail closed until approved durable person/workspace/destination limits exist. No account-match lookup or delivery. Existing recipient acceptance/cancel unchanged.';
CREATE TRIGGER private_invitation_preparation_guard BEFORE INSERT OR UPDATE ON public.account_connection_invitations FOR EACH ROW EXECUTE FUNCTION public.private_invitation_preparation_guard();
CREATE OR REPLACE FUNCTION public.request_existing_account_connection(_ws uuid,_target uuid,_confirmed boolean) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE recipient text; kind text; invitation uuid;person text;account text; BEGIN
 IF _confirmed IS DISTINCT FROM true OR NOT public.can_manage_account_connections(_ws) OR _ws=_target OR NOT EXISTS(SELECT 1 FROM public.workspaces WHERE id=_ws AND account_type IN ('private_pay','facility','hospital','provider')) OR NOT EXISTS(SELECT 1 FROM public.search_business_identities('signed_in','') WHERE workspace_id=_target) OR NOT EXISTS(SELECT 1 FROM auth.users WHERE id=auth.uid() AND email_confirmed_at IS NOT NULL) THEN RAISE EXCEPTION 'Connection unavailable'; END IF;
 PERFORM 1 FROM public.workspaces WHERE id=_ws FOR UPDATE;
 IF EXISTS(SELECT 1 FROM public.account_business_connections WHERE active AND ((workspace_a=_ws AND workspace_b=_target) OR (workspace_a=_target AND workspace_b=_ws))) THEN RAISE EXCEPTION 'Connection already active'; END IF;
 SELECT i.id INTO invitation FROM public.account_connection_invitations i WHERE i.inviter_workspace_id=_ws AND i.recipient_workspace_id=_target AND i.status='pending' AND i.expires_at>now() ORDER BY i.created_at DESC LIMIT 1; IF invitation IS NOT NULL THEN RETURN invitation; END IF;
 IF (SELECT count(*) FROM public.account_connection_invitations WHERE inviter_workspace_id=_ws AND created_at>now()-interval '1 hour')>=10 THEN RAISE EXCEPTION 'Connection unavailable'; END IF;
 SELECT lower(u.email),CASE WHEN w.account_type='provider' THEN 'provider' ELSE 'facility' END INTO recipient,kind FROM public.workspace_members m JOIN auth.users u ON u.id=m.user_id JOIN public.workspaces w ON w.id=m.workspace_id JOIN public.user_profiles p ON p.user_id=m.user_id WHERE m.workspace_id=_target AND m.role='owner' AND NOT m.is_contractor AND m.removed_at IS NULL AND u.email_confirmed_at IS NOT NULL AND p.status='active' AND NOT p.is_test_account AND p.deleted_at IS NULL ORDER BY m.created_at LIMIT 1;
 IF recipient IS NULL THEN RAISE EXCEPTION 'Connection unavailable'; END IF;
 SELECT mfn_id INTO person FROM public.user_profiles WHERE user_id=auth.uid();SELECT mfn_id INTO account FROM public.workspaces WHERE id=_ws;
 INSERT INTO public.account_connection_invitations(inviter_workspace_id,recipient_workspace_id,recipient_email,intended_type,intended_account_type,token_hash,expires_at,created_by,person_mfn_id,workspace_mfn_id,delivery_status) VALUES(_ws,_target,recipient,kind,kind,encode(extensions.digest(extensions.gen_random_bytes(32),'sha256'),'hex'),now()+interval '7 days',auth.uid(),person,account,'not_sent') RETURNING id INTO invitation;
 INSERT INTO public.account_relationship_events(workspace_id,invitation_id,action,actor_id,person_mfn_id,workspace_mfn_id,details) VALUES(_ws,invitation,'connection_requested',auth.uid(),person,account,jsonb_build_object('recipient_workspace_id',_target,'delivery','off'));
 RETURN invitation; END $$;
